def parse_fia_simulation_csv(datafile):
    list_converter = lambda x: map(int, )

    df_xyhs = pd.read_csv(datafile, converters={
        "x": literal_eval,
        "y": literal_eval,
        "h": literal_eval,
        "s": literal_eval,
    }, nrows=_sage_const_1 )

    x = df_xyhs.x[_sage_const_0 ]
    y = df_xyhs.y[_sage_const_0 ]
    h = df_xyhs.h[_sage_const_0 ]
    s = df_xyhs.s[_sage_const_0 ]

    df = pd.read_csv(datafile, skiprows=_sage_const_2 )

    return (x, y), (h, s), df

def extract_possible_support(df):
    f = list(df.failure_rate)
    n = len(df)

    possible_support = set()
    for i in range(n):
        if i % _sage_const_64  == _sage_const_0 :
            possible_support.add(i)
            continue
        # if i == 0: continue

        if f[i] == _sage_const_0  and f[i - _sage_const_1 ] == _sage_const_1 :
            possible_support.add(i)
            possible_support.add(i + _sage_const_1 )
            possible_support.add(i + _sage_const_2 )
            possible_support.add(i + _sage_const_3 )

    return possible_support


def test_if_key_recovery_is_possible(datafile):
    (x, y), (h, s), df = parse_fia_simulation_csv(datafile)

    n = len(df)
    w = len(x)

    print(y)
    y_candidate_support = extract_possible_support(df)
    print(f'{len(y_candidate_support)=}')
    print(f'{len(set(y) - set(y_candidate_support))=}')
    if (len(set(y) - set(y_candidate_support))):
        print('[-] Oh no, key recovery is not possible!')
        print('set(y) - set(y_candidate_support) = ', set(y) - set(y_candidate_support))
        return False

    n_zeros_needed = len(y_candidate_support)
    complexity = _sage_const_1  / (binomial(n - w, n_zeros_needed)/binomial(n, n_zeros_needed))
    print('Attack complexity = ', numerical_approx(complexity))

    return [numerical_approx(complexity), n - len(y_candidate_support)]


